SINA_SMART["histo1-cartilage"] = {"lecture":"histo1-cartilage","title":"Cartilage","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"histo1-cartilage:e0","text":"Cartilage: firm, resilient, avascular; model for bone.","topic":"Cartilage: characteristics","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-cartilage:e2","text":"Matrix 95% of volume: type II collagen, hyaluronan, proteoglycans (chondroitin, keratan sulphate).","topic":"Cells and matrix","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-cartilage:e3","text":"Territorial matrix darker around lacunae; interterritorial paler.","topic":"Cells and matrix","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-cartilage:e1","text":"Chondroblasts (young, perichondrium) → chondrocytes (in lacunae, isogenous groups).","topic":"Perichondrium and growth","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-cartilage:e4","text":"Perichondrium: outer fibrous + inner chondrogenic; nutrition, growth, repair.","topic":"Perichondrium and growth","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-cartilage:e5","text":"Appositional growth = surface (girth); interstitial = from within.","topic":"Perichondrium and growth","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-cartilage:e6","text":"Hyaline: glassy; joints, trachea, ribs, nose, growth plates.","topic":"Hyaline, elastic and fibrocartilage","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-cartilage:e7","text":"Elastic: elastic fibres; ear, epiglottis.","topic":"Hyaline, elastic and fibrocartilage","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-cartilage:e8","text":"Fibrocartilage: collagen bundles, no perichondrium; discs, menisci, pubic symphysis.","topic":"Hyaline, elastic and fibrocartilage","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"histo1-cartilage:e9","text":"Articular cartilage has no perichondrium either.","topic":"Hyaline, elastic and fibrocartilage","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"9gxf4u":"a","1cs4opt":"a","1onptjp":"a","1hgqtp4":"a","18eahzc":"a","by0lyu":"a","1tvxlyu":"a","15rq43l":"a","td5qn6":"a","d9tesx":"a","1nq1hmq":"a","3juynl":"a","fgkdwe":"a","2z1ig7":"a","crj1h1":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"histo1-cartilage:e0":{"s":0,"u":["Cartilage: firm, resilient, avascular; model for bone.","Cartilage is a firm, resilient, specialised connective tissue that bears stress without permanent distortion.","Functions: attachments, protection of tissues and a model for developing bone ."],"dp":[]},"histo1-cartilage:e2":{"s":1,"u":["Matrix 95% of volume: type II collagen, hyaluronan, proteoglycans (chondroitin, keratan sulphate).","The matrix (95% of the volume) contains type II collagen and ground substance: hyaluronan and proteoglycans (a core protein with chondroitin and keratan sulphate), very hydrated so it resists compression."],"dp":[]},"histo1-cartilage:e3":{"s":1,"u":["Territorial matrix darker around lacunae; interterritorial paler.","Around each lacuna, the territorial matrix stains darker; the paler interterritorial matrix lies between groups."],"dp":[]},"histo1-cartilage:e1":{"s":2,"u":["Chondroblasts (young, perichondrium) → chondrocytes (in lacunae, isogenous groups).","Interstitial growth : existing chondrocytes divide inside their lacunae, forming isogenous groups that secrete more matrix: growth from within, as in epiphyseal plates."],"dp":[]},"histo1-cartilage:e4":{"s":2,"u":["Perichondrium: outer fibrous + inner chondrogenic; nutrition, growth, repair.","It provides nutrition , appositional growth and repair .","The perichondrium has two layers: an outer fibrous layer (dense CT) and an inner chondrogenic layer (loose CT, chondroblasts, blood vessels)."],"dp":[]},"histo1-cartilage:e5":{"s":2,"u":["Appositional growth = surface (girth); interstitial = from within.","Appositional growth : new cartilage is added on the surface by chondrogenic cells of the perichondrium differentiating into chondroblasts: growth in girth.","Interstitial growth : existing chondrocytes divide inside their lacunae, forming isogenous groups that secrete more matrix: growth from within, as in epiphyseal plates."],"dp":[]},"histo1-cartilage:e6":{"s":3,"u":["Hyaline: glassy; joints, trachea, ribs, nose, growth plates.","Sites: fetal skeleton, trachea, most laryngeal cartilages, articular cartilage , ends of ribs, external nose, epiphyseal plates ."],"dp":[]},"histo1-cartilage:e7":{"s":3,"u":["Elastic: elastic fibres; ear, epiglottis.","Elastic cartilage : dense elastic fibre network (Weigert stain), larger chondrocytes usually single, perichondrium; flexible support.","Sites: external ear, epiglottis , corniculate and cuneiform cartilages."],"dp":[]},"histo1-cartilage:e8":{"s":3,"u":["Fibrocartilage: collagen bundles, no perichondrium; discs, menisci, pubic symphysis.","Sites: pubic symphysis, annulus fibrosus of the intervertebral disc, menisci of the knee, some tendon insertions.","Fibrocartilage : a combination of dense regular CT and hyaline cartilage; thick collagen bundles with chondrocytes singly or in rows; no perichondrium ; support, rigidity and shock absorption."],"dp":[]},"histo1-cartilage:e9":{"s":3,"u":["Articular cartilage has no perichondrium either.","Sites: fetal skeleton, trachea, most laryngeal cartilages, articular cartilage , ends of ribs, external nose, epiphyseal plates .","Hyaline cartilage , the most abundant: translucent, glassy, highly basophilic homogeneous matrix (collagen fibres invisible because they share the ground substance's refractive index), isogenous groups, perichondrium (except articular cartilage)."],"dp":[{"h":"Why joint cartilage heals so poorly","t":"Articular cartilage has no blood vessels, no nerves and, unlike most hyaline cartilage, no perichondrium . The perichondrium is the source of new chondroblasts for repair, and blood brings the inflammatory cells that start healing elsewhere. So a defect in joint cartilage is filled, if at all, by weaker fibrocartilage from the underlying bone marrow, and damage tends to accumulate over the years as osteoarthritis. The same avascularity makes cartilage a good graft: with no vessels, it is less exposed to the immune system. Source: the lecture's avascularity and perichondrium functions."}]}},"meta":{"9gxf4u":{"a":"recall","vg":"histo1-cartilage:e3/recall/1"},"1cs4opt":{"a":"recall","vg":"histo1-cartilage:e2/recall/1"},"1onptjp":{"a":"recall","vg":"histo1-cartilage:e1/recall/1"},"1hgqtp4":{"a":"recall","vg":"histo1-cartilage:e1/recall/2"},"18eahzc":{"a":"recall","vg":"histo1-cartilage:e5/recall/1"},"by0lyu":{"a":"recall","vg":"histo1-cartilage:e4/recall/1"},"1tvxlyu":{"a":"recall","vg":"histo1-cartilage:e9/recall/1"},"15rq43l":{"a":"recall","vg":"histo1-cartilage:e7/recall/1"},"td5qn6":{"a":"recall","vg":"histo1-cartilage:e8/recall/1"},"d9tesx":{"a":"recall","vg":"histo1-cartilage:e8/recall/2"},"1nq1hmq":{"a":"recall","vg":"histo1-cartilage:e6/recall/1"},"3juynl":{"a":"recall","vg":"histo1-cartilage:e9/recall/2"},"fgkdwe":{"a":"recall","vg":"histo1-cartilage:e4/recall/2"},"2z1ig7":{"a":"recall","vg":"histo1-cartilage:e2/recall/2"},"crj1h1":{"a":"recall","vg":"histo1-cartilage:e7/recall/1"}},"explRev":"7877f0eb28d0"};
